package com.securevault.service;
import com.securevault.entity.*;import com.securevault.repository.DeviceRepository;import jakarta.servlet.http.HttpServletRequest;import org.springframework.stereotype.Service;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
@Service public class DeviceService{private final DeviceRepository repo;public DeviceService(DeviceRepository r){repo=r;}public String deviceName(String ua){if(ua==null)return"Unknown device";if(ua.contains("Windows"))return"Windows device";if(ua.contains("Mac"))return"Mac device";if(ua.contains("Android"))return"Android device";if(ua.contains("iPhone"))return"iPhone";return"Browser device";}public String fingerprint(String ua,String ip){try{return Base64.getEncoder().encodeToString(MessageDigest.getInstance("SHA-256").digest((String.valueOf(ua)+"|"+ip).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){return String.valueOf(ua)+ip;}}public void record(User u,HttpServletRequest r){String f=fingerprint(r.getHeader("User-Agent"),r.getRemoteAddr());Device d=repo.findByUserAndFingerprint(u,f).orElseGet(()->{Device x=new Device();x.setUser(u);x.setFingerprint(f);x.setName(deviceName(r.getHeader("User-Agent")));x.setFirstSeen(java.time.LocalDateTime.now());return x;});d.setBrowser(r.getHeader("User-Agent"));d.setIpAddress(r.getRemoteAddr());d.setLastSeen(java.time.LocalDateTime.now());repo.save(d);}}
